@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap');

:root {
  --ink: #20252f;
  --muted: #78808d;
  --line: #e8e9ed;
  --purple: #6558d3;
  --purple-dark: #5145b8;
  --soft: #f5f4ff;
  --green: #46a57b;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  color: var(--ink);
  font-family: 'DM Sans', sans-serif;
  background: #f4f5f8;
  background-image: radial-gradient(circle at 12% 12%, #e5e3ff 0, transparent 28%), radial-gradient(circle at 90% 88%, #dff5ed 0, transparent 25%);
}
.app-shell { width: min(100% - 32px, 640px); margin: 0 auto; padding: 8vh 0 30px; }
.todo-card { background: rgba(255,255,255,.94); border: 1px solid rgba(255,255,255,.8); border-radius: 24px; padding: clamp(25px, 5vw, 44px); box-shadow: 0 22px 55px rgba(38, 42, 66, .11); }
.app-header { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 32px; }
.eyebrow { color: var(--purple); font-size: 11px; font-weight: 800; letter-spacing: .16em; margin: 0 0 11px; }
h1, h2 { font-family: 'Plus Jakarta Sans', sans-serif; margin: 0; }
h1 { font-size: clamp(30px, 6vw, 43px); letter-spacing: -.055em; }
.subtitle { color: var(--muted); margin: 8px 0 0; font-size: 15px; }
.header-mark { display: grid; place-items: center; width: 46px; height: 46px; color: white; font-size: 23px; border-radius: 15px; background: var(--purple); box-shadow: 0 8px 17px rgba(101,88,211,.25); }
.add-form { display: flex; gap: 10px; margin-bottom: 34px; }
.add-form input { min-width: 0; flex: 1; border: 1px solid var(--line); border-radius: 12px; padding: 15px 17px; color: var(--ink); font: inherit; outline: none; transition: .2s; }
.add-form input:focus { border-color: var(--purple); box-shadow: 0 0 0 4px rgba(101,88,211,.11); }
.add-form button { border: 0; border-radius: 12px; padding: 0 18px; color: white; background: var(--purple); font: 600 14px 'DM Sans', sans-serif; cursor: pointer; transition: .2s; }
.add-form button span { font-size: 19px; vertical-align: -1px; margin-left: 5px; }
.add-form button:hover { background: var(--purple-dark); transform: translateY(-1px); }
.list-heading { display: flex; justify-content: space-between; align-items: center; margin-bottom: 13px; }
h2 { font-size: 17px; }
.list-heading p { color: var(--muted); font-size: 13px; margin: 0; }
.list-heading p span:first-child { color: var(--purple); font-weight: 700; }
.task-list { display: grid; gap: 9px; }
.task { display: flex; align-items: center; gap: 13px; padding: 14px 13px; border: 1px solid var(--line); border-radius: 13px; animation: appear .22s ease-out; }
@keyframes appear { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: none; } }
.task-text { flex: 1; overflow-wrap: anywhere; font-size: 15px; line-height: 1.4; }
.task[data-completed="true"] .task-text { color: #a1a6af; text-decoration: line-through; }
.task-complete { appearance: none; width: 20px; height: 20px; flex: 0 0 20px; margin: 0; border: 2px solid #d2d5dc; border-radius: 50%; cursor: pointer; position: relative; transition: .2s; }
.task-complete:checked { border-color: var(--green); background: var(--green); }
.task-complete:checked::after { content: '✓'; position: absolute; color: white; font-size: 13px; font-weight: bold; left: 2px; top: -1px; }
.task-delete { border: 0; background: transparent; color: #b0b4bc; font-size: 20px; line-height: 1; cursor: pointer; padding: 3px 5px; }
.task-delete:hover { color: #df6262; }
.empty-state { color: var(--muted); text-align: center; font-size: 14px; padding: 26px 0 10px; margin: 0; }
.footer-note { color: #989da8; text-align: center; font-size: 12px; margin: 20px 0 0; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 480px) { .add-form { flex-direction: column; } .add-form button { min-height: 46px; } }

